let bytes: Uint8Array | null = null;

/** EngineFogNoiseBytes: the 262144 texels, 64 * 64 * 64, index (z * 64 + y) * 64 + x. Decoded on the first call. */
export function engineFogNoiseBytes(): Uint8Array {
  if (bytes) return bytes;
  const s = atob(FOG_NOISE_B64);
  const b = new Uint8Array(s.length);
  for (let i = 0; i < s.length; i++) b[i] = s.charCodeAt(i);
  bytes = b;
  return b;
}

/** EngineFogNoiseHash: FNV-1a32 of the 262144 bytes (the engine's is 0x94fba76f). */
export function engineFogNoiseHash(): number {
  const n = engineFogNoiseBytes();
  let h = 2166136261;
  for (let i = 0; i < 64 * 64 * 64; i++) {
    h ^= n[i]!;
    h = Math.imul(h, 16777619) >>> 0;
  }
  return h >>> 0;
}
